cat <<'EOF' > src/main.rs
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};

struct Config {
    check: bool,
    print: bool,
    fail_on_change: bool,
    wrap: bool,
    wraplen: usize,
    wrapmin: usize,
    tabsize: usize,
    usetabs: bool,
    stdin: bool,
    verbose: bool,
    quiet: bool,
    trace: bool,
    recursive: bool,
    lists: Vec<String>,
    verbatims: Vec<String>,
    no_indent_envs: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            check: false,
            print: false,
            fail_on_change: false,
            wrap: true,
            wraplen: 80,
            wrapmin: 70,
            tabsize: 2,
            usetabs: false,
            stdin: false,
            verbose: false,
            quiet: false,
            trace: false,
            recursive: false,
            lists: vec![
                "itemize".to_string(),
                "enumerate".to_string(),
                "description".to_string(),
                "inlineroman".to_string(),
                "inventory".to_string(),
            ],
            verbatims: vec![
                "verbatim".to_string(),
                "Verbatim".to_string(),
                "lstlisting".to_string(),
                "minted".to_string(),
                "comment".to_string(),
            ],
            no_indent_envs: vec!["document".to_string()],
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut config = Config::default();
    let mut files = Vec::new();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-c" | "--check" => config.check = true,
            "-p" | "--print" => config.print = true,
            "-f" | "--fail-on-change" => config.fail_on_change = true,
            "-n" | "--nowrap" => config.wrap = false,
            "-l" | "--wraplen" => {
                i += 1;
                config.wraplen = args[i].parse().unwrap();
                if config.wraplen < 50 {
                    config.wrapmin = config.wraplen;
                } else {
                    config.wrapmin = config.wraplen - 10;
                }
            }
            "-t" | "--tabsize" => {
                i += 1;
                config.tabsize = args[i].parse().unwrap();
            }
            "--usetabs" => config.usetabs = true,
            "-s" | "--stdin" => config.stdin = true,
            "-v" | "--verbose" => config.verbose = true,
            "-q" | "--quiet" => config.quiet = true,
            "--trace" => config.trace = true,
            "-r" | "--recursive" => config.recursive = true,
            "--args" => {
                print_args(&config);
                return;
            }
            "-V" | "--version" => {
                println!("tex-fmt 0.5.6");
                return;
            }
            "-h" | "--help" => {
                print_help();
                return;
            }
            arg if arg.starts_with('-') => {
                // Ignore unknown flags for now
            }
            arg => {
                files.push(arg.to_string());
            }
        }
        i += 1;
    }

    if config.stdin {
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).unwrap();
        let formatted = format_latex(&input, &config);
        print!("{}", formatted);
        return;
    }

    if files.is_empty() && config.recursive {
        files.push(".".to_string());
    }

    let mut all_files = Vec::new();
    for file in files {
        if config.recursive {
            find_files(Path::new(&file), &mut all_files);
        } else {
            all_files.push(PathBuf::from(file));
        }
    }

    let mut exit_code = 0;
    for file_path in all_files {
        let content = match fs::read_to_string(&file_path) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("ERROR: tex-fmt {}: Could not open file. ", file_path.display());
                exit_code = 1;
                continue;
            }
        };

        let formatted = format_latex(&content, &config);

        if config.check {
            if content != formatted {
                eprintln!("ERROR: tex-fmt {}: Incorrect formatting. ", file_path.display());
                exit_code = 1;
            }
        } else if config.print {
            print!("{}", formatted);
        } else {
            if content != formatted {
                fs::write(&file_path, &formatted).unwrap();
                if config.fail_on_change {
                    exit_code = 1;
                }
            }
        }
    }

    std::process::exit(exit_code);
}

fn find_files(path: &Path, all_files: &mut Vec<PathBuf>) {
    if path.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                find_files(&entry.path(), all_files);
            }
        }
    } else {
        if let Some(ext) = path.extension() {
            if ext == "tex" || ext == "bib" || ext == "cls" || ext == "sty" {
                all_files.push(path.to_path_buf());
            }
        }
    }
}

fn print_args(config: &Config) {
    println!("tex-fmt");
    println!("  check:                   {}", config.check);
    println!("  print:                   {}", config.print);
    println!("  fail-on-change:          {}", config.fail_on_change);
    println!("  wrap:                    {}", config.wrap);
    println!("  wraplen:                 {}", config.wraplen);
    println!("  wrapmin:                 {}", config.wrapmin);
    println!("  tabsize:                 {}", config.tabsize);
    println!("  tabchar:                 {}", if config.usetabs { "tab" } else { "space" });
    println!("  stdin:                   {}", config.stdin);
    println!("  config:                  None");
    println!("  verbosity:               {}", if config.quiet { "quiet" } else if config.verbose { "verbose" } else { "warn" });
    println!("  lists:                   {}", config.lists.join("\n                           "));
    println!("  verbatims:               {}", config.verbatims.join("\n                           "));
    println!("  no-indent-envs:          {}", config.no_indent_envs.join("\n                           "));
    println!("  wrap-chars:               ");
}

fn print_help() {
    println!("tex-fmt 0.5.6\n\nLaTeX formatter written in Rust\n\nUsage: executable [OPTIONS] [files]...\n\nArguments:\n  [files]...  List of files to be formatted\n\nOptions:\n  -c, --check               Check formatting, do not modify files\n  -p, --print               Print to stdout, do not modify files\n  -f, --fail-on-change      Format files and return non-zero exit code if files are modified\n  -n, --nowrap              Do not wrap long lines\n  -l, --wraplen <N>         Line length for wrapping [default: 80]\n  -t, --tabsize <N>         Number of characters to use as tab size [default: 2]\n      --usetabs             Use tabs instead of spaces for indentation\n  -s, --stdin               Process stdin as a single file, output to stdout\n      --config <PATH>       Path to config file\n      --noconfig            Do not read any config file\n  -v, --verbose             Show info messages\n  -q, --quiet               Hide warning messages\n      --trace               Show trace messages\n      --completion <SHELL>  Generate shell completion script [possible values: bash, elvish, fish, powershell, zsh]\n      --man                 Generate man page\n      --args                Print arguments passed to tex-fmt and exit\n  -r, --recursive           Recursively search for files to format\n  -h, --help                Print help\n  -V, --version             Print version");
}

fn format_latex(input: &str, config: &Config) -> String {
    // Basic implementation for now
    let mut output = String::new();
    let mut current_indent = 0;
    let mut in_verbatim = false;
    let mut verbatim_end_tag = String::new();

    // First, split lines and handle the \begin, \end, \item split
    let lines = preprocess(input, config);

    for line in lines {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            output.push_str("\n");
            continue;
        }

        // Handle verbatim
        if in_verbatim {
            output.push_str(&line);
            output.push_str("\n");
            if trimmed.contains(&verbatim_end_tag) {
                in_verbatim = false;
            }
            continue;
        }

        let mut is_verbatim_start = false;
        for verb in &config.verbatims {
            let start_tag = format!("\\begin{{{}}}", verb);
            if trimmed.contains(&start_tag) {
                is_verbatim_start = true;
                verbatim_end_tag = format!("\\end{{{}}}", verb);
                break;
            }
        }

        if is_verbatim_start {
            in_verbatim = true;
            // Verbatim lines are not indented or wrapped
            output.push_str(&line);
            output.push_str("\n");
            continue;
        }

        // Normal line
        // TODO: Indentation and wrapping
        output.push_str(&line);
        output.push_str("\n");
    }

    output
}

fn preprocess(input: &str, config: &Config) -> Vec<String> {
    // Placeholder
    input.lines().map(|s| s.to_string()).collect()
}
EOF
"}

