fn format_latex(input: &str, config: &Config) -> String {
    let mut formatted = String::new();
    let mut stack = Vec::new();
    let mut in_verbatim = false;
    let mut verb_end = String::new();
    let mut last_was_empty = false;

    for line in preprocess(input) {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if !last_was_empty { formatted.push('\n'); last_was_empty = true; }
            continue;
        }
        last_was_empty = false;

        if in_verbatim {
            formatted.push_str(&line);
            formatted.push('\n');
            if trimmed.contains(&verb_end) { in_verbatim = false; }
            continue;
        }

        let mut is_verb_start = false;
        for v in &config.verbatims {
            if trimmed.starts_with(&format!("\\begin{{{}}}", v)) {
                is_verb_start = true;
                verb_end = format!("\\end{{{}}}", v);
                break;
            }
        }
        if is_verb_start {
            in_verbatim = true;
            formatted.push_str(&line);
            formatted.push('\n');
            continue;
        }

        // Handle \end before indentation calculation
        if trimmed.starts_with("\\end{") {
            if let Some(pos) = trimmed.find('}') {
                let env = &trimmed[5..pos];
                if !config.no_indent_envs.contains(&env.to_string()) { stack.pop(); }
            }
        }

        let mut indent = 0;
        for env in &stack {
            if config.lists.contains(env) { indent += 2 * config.tabsize; }
            else { indent += config.tabsize; }
        }

        let mut is_item = false;
        if trimmed.starts_with("\\item") {
            if let Some(last_env) = stack.last() {
                if config.lists.contains(last_env) {
                    indent -= config.tabsize;
                    is_item = true;
                }
            }
        }

        let wrap_indent = if is_item { indent + config.tabsize } else { indent };
        let wrapped_lines = wrap_line(trimmed, indent, wrap_indent, config);
        for wl in wrapped_lines {
            formatted.push_str(&wl);
            formatted.push('\n');
        }

        // Handle \begin after indentation calculation
        if trimmed.starts_with("\\begin{") {
            if let Some(pos) = trimmed.find('}') {
                let env = &trimmed[7..pos];
                if !config.no_indent_envs.contains(&env.to_string()) && !config.verbatims.contains(&env.to_string()) {
                    stack.push(env.to_string());
                }
            }
        }
    }
    formatted
}

fn preprocess(input: &str) -> Vec<String> {
    let mut result = Vec::new();
    for line in input.lines() {
        let mut s = line.to_string();
        // A very simple split. In reality, should handle comments and multiple tokens.
        // For now, let's just use it as is.
        result.push(s);
    }
    result
}

fn wrap_line(line: &str, first_indent: usize, rest_indent: usize, config: &Config) -> Vec<String> {
    if !config.wrap || line.is_empty() {
        let indent_str = if config.usetabs { "\t".repeat(first_indent / config.tabsize) } else { " ".repeat(first_indent) };
        return vec![format!("{}{}", indent_str, line)];
    }
    let words: Vec<&str> = line.split_whitespace().collect();
    if words.is_empty() { return vec![String::new()]; }

    let mut result = Vec::new();
    let mut current_line = String::new();
    let mut current_indent = first_indent;

    for word in words {
        let space = if current_line.is_empty() { 0 } else { 1 };
        if current_indent + current_line.len() + space + word.len() > config.wraplen && !current_line.is_empty() {
            let indent_str = if config.usetabs { "\t".repeat(current_indent / config.tabsize) } else { " ".repeat(current_indent) };
            result.push(format!("{}{}", indent_str, current_line));
            current_line = word.to_string();
            current_indent = rest_indent;
        } else {
            if !current_line.is_empty() { current_line.push(' '); }
            current_line.push_str(word);
        }
    }
    let indent_str = if config.usetabs { "\t".repeat(current_indent / config.tabsize) } else { " ".repeat(current_indent) };
    result.push(format!("{}{}", indent_str, current_line));
    result
}
