use std::io::{self, Read};
use std::path::{Path, PathBuf};

struct Config {
    check: bool,
    print: bool,
    fail_on_change: bool,
    wrap: bool,
    wraplen: usize,
    wrapmin: usize,
    tabsize: usize,
    usetabs: bool,
    stdin: bool,
    recursive: bool,
    lists: Vec<String>,
    verbatims: Vec<String>,
    no_indent_envs: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            check: false, print: false, fail_on_change: false, wrap: true, wraplen: 80, wrapmin: 70, tabsize: 2, usetabs: false, stdin: false, recursive: false,
            lists: vec!["itemize", "enumerate", "description", "inlineroman", "inventory"].iter().map(|s| s.to_string()).collect(),
            verbatims: vec!["verbatim", "Verbatim", "lstlisting", "minted", "comment"].iter().map(|s| s.to_string()).collect(),
            no_indent_envs: vec!["document"].iter().map(|s| s.to_string()).collect(),
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut config = Config::default();
    let mut files = Vec::new();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-c" | "--check" => config.check = true,
            "-p" | "--print" => config.print = true,
            "-f" | "--fail-on-change" => config.fail_on_change = true,
            "-n" | "--nowrap" => config.wrap = false,
            "-l" | "--wraplen" => { i += 1; config.wraplen = args[i].parse().unwrap(); if config.wraplen < 50 { config.wrapmin = config.wraplen; } else { config.wrapmin = config.wraplen - 10; } }
            "-t" | "--tabsize" => { i += 1; config.tabsize = args[i].parse().unwrap(); }
            "--usetabs" => config.usetabs = true,
            "-s" | "--stdin" => config.stdin = true,
            "-r" | "--recursive" => config.recursive = true,
            "--args" => { print_args(&config); return; }
            "-V" | "--version" => { println!("tex-fmt 0.5.6"); return; }
            "-h" | "--help" => { print_help(); return; }
            arg if arg.starts_with('-') => {}
            arg => files.push(arg.to_string()),
        }
        i += 1;
    }

    if config.stdin {
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).unwrap();
        print!("{}", format_latex(&input, &config));
        return;
    }
    if files.is_empty() && config.recursive { files.push(".".to_string()); }
    let mut all_files = Vec::new();
    for file in files {
        if config.recursive { find_files(Path::new(&file), &mut all_files); }
        else { all_files.push(PathBuf::from(file)); }
    }
    let mut exit_code = 0;
    for file_path in all_files {
        let content = match fs::read_to_string(&file_path) {
            Ok(c) => c,
            Err(_) => { eprintln!("ERROR: tex-fmt {}: Could not open file. ", file_path.display()); exit_code = 1; continue; }
        };
        let formatted = format_latex(&content, &config);
