fn wrap_line(line: &str, first_indent: usize, rest_indent: usize, config: &Config) -> Vec<String> {
    if !config.wrap || line.is_empty() {
        let indent_str = if config.usetabs { "\t".repeat(first_indent / config.tabsize) } else { " ".repeat(first_indent) };
        return vec![format!("{}{}", indent_str, line)];
    }
    let words: Vec<&str> = line.split_whitespace().collect();
    if words.is_empty() { return vec![String::new()]; }
    let mut result = Vec::new();
    let mut current_line = String::new();
    let mut current_indent = first_indent;
    for word in words {
        let space = if current_line.is_empty() { 0 } else { 1 };
        if current_indent + current_line.chars().count() + space + word.chars().count() > config.wraplen && !current_line.is_empty() {
            let indent_str = if config.usetabs { "\t".repeat(current_indent / config.tabsize) } else { " ".repeat(current_indent) };
            result.push(format!("{}{}", indent_str, current_line));
            current_line = word.to_string();
            current_indent = rest_indent;
        } else {
            if !current_line.is_empty() { current_line.push(' '); }
            current_line.push_str(word);
        }
    }
    let indent_str = if config.usetabs { "\t".repeat(current_indent / config.tabsize) } else { " ".repeat(current_indent) };
    result.push(format!("{}{}", indent_str, current_line));
    result
}
